import{z as i,x as o,o as B,c as s,q as A,j as t,D as a,d as l,s as n,S as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"非传递性与对手课程","description":"","frontmatter":{"title":"非传递性与对手课程","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/sgt-nontransitivity.md","filePath":"llm/sgt-nontransitivity.md","lastUpdated":1791063341000}'),p={name:"llm/sgt-nontransitivity.md"};function d(C,E,F,m,h,_){const e=o("Mermaid");return B(),s("div",null,[E[2]||(E[2]=A('<h1 id="非传递性与对手课程" tabindex="-1">非传递性与对手课程 <a class="header-anchor" href="#非传递性与对手课程" aria-label="Permalink to &quot;非传递性与对手课程&quot;">​</a></h1><div class="epigraph"><p>A 赢 B、B 赢 C，不蕴含 A 赢 C：策略强弱不是一条数轴，而是一张带环的图；把带环的图压成数轴，环上的一切都成了「噪声」。</p><footer>—— 据 Balduzzi et al., Open-Ended Learning in Symmetric Games, 2019；Czarnecki et al., Real World Games Look Like Spinning Tops, 2020 整理</footer></div><p><a href="/llm/sgt-psro-opponent-pool">上一课</a>把对手池立成显式对象，结尾留下隐患：池上均衡只对池内分布有保证，池外策略照样能打穿你。本课解释为什么池外永远有——策略空间的强弱关系天生非传递，任何有限的对手课程都是在带环的图上采样的有限点集。这是「语言模型的自博弈」单元的第一课：前面四课的理论在棋盘上最干净，从这里起，处处以语言模型为对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>传递性是单标量评测的前提：若强弱能排成一条线（Elo、天梯、成绩单），「谁更强」才有唯一答案，训练沿坡向上爬就是全部剧情。但策略博弈的胜负矩阵没有义务传递：石头胜剪刀、剪刀胜布、布胜石头，三个策略互为循环，任何标量序都强行判三人名次，被判「最弱」的那位其实能克制冠军。Balduzzi 等人 2019 把策略空间分解成<strong>传递部分</strong>（可排序的强度轴）与<strong>非传递部分</strong>（循环维），并证明循环维在上千万玩家的真实对局数据里不可忽略——Czarnecki 等人 2020 测量发现：真实游戏整体长得像陀螺，大头是传递的主轴，但尾巴（循环维）普遍存在，正是「老将克制新锐、新锐横扫前辈」现象的来源。</p><p><span class="marginnote">数字实例：石头-剪刀-布就是最小的环。给三者强行排名，「布」可能被评为末位，可它恰好克制冠军「石头」——环被压扁成一条线时，「克冠军的人」在成绩单上就成了账面噪声。这就是标量评测对循环维干的手术。</span></p><p>对自博弈课程，这是结构性麻烦：对手课程的本质是按某种标量挑对手、逐级加难（主干课的<a href="/llm/rl-difficulty-curriculum">难度课程</a>在单智能体里这么做没有问题，因为难度本身在一条线上）。而在非传递空间里，任何标量排序都会把环切掉：按 Elo 挑「略强于我」的对手，等于只在传递轴上采样，模型沿主轴爬坡，环上的策略空间从未访问——直到上线被一个真用户用环上招式打穿。</p><h3 id="环不会练没-只能练全" tabindex="-1">环不会练没，只能练全 <a class="header-anchor" href="#环不会练没-只能练全" aria-label="Permalink to &quot;环不会练没，只能练全&quot;">​</a></h3><p>非传递部分不随训练自动消失：两个模型互相追，往往在环上同步旋转而不是消环。能做的是<strong>覆盖</strong>：对手池要有意识地包含「克制当前模型」的循环向对手（PSRO 的挖掘者角色干的就是这个），评测要按对局矩阵而非单一名次报告。语言模型的自博弈（如 SPIN，Chen 等 2024）常被报告为单向进步，那是评测集恰落在传递轴附近的结果——换一组会设环的评测，结论可以翻转。</p><p><span class="marginnote">Elo 体系假设对局可近似为传递的（Elo 1978 的原始场景是棋类，循环相对少）。把 Elo 直接搬到生成模型的偏好对比上，等于隐式宣称循环维为零——这一步通常没人论证。</span></p>',10)),(B(),t(r,null,{default:a(()=>[n(e,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20WIN%5B%22%E8%83%9C%E8%B4%9F%E7%9F%A9%E9%98%B5%22%5D%20--%3E%20DECOMP%5B%22%E5%88%86%E8%A7%A3%EF%BC%9A%E4%BC%A0%E9%80%92%E8%BD%B4%20%2B%20%E5%BE%AA%E7%8E%AF%E7%BB%B4%22%5D%0A%20%20DECOMP%20--%3E%20AX%5B%22%E4%BC%A0%E9%80%92%E8%BD%B4%EF%BC%9A%E5%8F%AF%E6%8E%92%E5%BA%8F%EF%BC%8CElo%20%E5%8F%AF%E7%94%A8%22%5D%0A%20%20DECOMP%20--%3E%20CYC%5B%22%E5%BE%AA%E7%8E%AF%E7%BB%B4%EF%BC%9ARPS%20%E5%9E%8B%E7%8E%AF%EF%BC%8C%E4%B8%8D%E5%8F%AF%E6%8E%92%E5%BA%8F%22%5D%0A%20%20AX%20--%3E%20CUR%5B%22%E5%AF%B9%E6%89%8B%E8%AF%BE%E7%A8%8B%EF%BC%9A%E6%B2%BF%E8%BD%B4%E5%8A%A0%E9%9A%BE%22%5D%0A%20%20CYC%20--%3E%20POOL%5B%22%E5%AF%B9%E6%89%8B%E6%B1%A0%E8%A1%A5%E7%8E%AF%EF%BC%9A%E4%B8%93%E8%AE%BE%E5%85%8B%E5%88%B6%E5%9E%8B%E5%AF%B9%E6%89%8B%22%5D%0A%20%20CUR%20--%3E%20GAP%5B%22%E5%8F%AA%E6%B2%BF%E8%BD%B4%E8%AE%AD%E7%BB%83%20%E2%86%92%20%E7%8E%AF%E4%B8%8A%E7%9B%B2%E5%8C%BA%22%5D%0A%20%20POOL%20--%3E%20FIX%5B%22%E7%9B%B2%E5%8C%BA%E8%A1%A5%E4%B8%81%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[l(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>本课的方法是<strong>矩阵分解加审计协议</strong>：借 Balduzzi 等人的分解把胜负矩阵拆成传递轴与循环维，说明单标量评测为什么只看得见前者；再取 Czarnecki 等人的测量定形——真实博弈像陀螺，主轴是大头、尾巴普遍有环。落成两个工程方法：对手池按「对当前模型胜率的凹陷」补环，评测报告对已知环结构对手组的胜率向量而非标量均值。方法上的钉子：环不会练没，只能显式覆盖。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么朴素自博弈偏爱传递轴？因为「赢过上一代」的梯度信号天然沿「我刚能打过谁」推进，而传递轴正是「能打过关系」的骨架；循环维的策略在自评里互相抵消（我克制你、他克制我），看起来是噪声，容易被训练流水线当随机波动滤掉。于是课程设计必须<strong>对抗这个倾向</strong>：对手选择不能只按胜率排序，要按「对我胜率的凹陷」选——谁最克制当前模型，谁优先入池（PSRO 的响应训练正是找这个凹陷；主干课对手选择一课的偏置分析在此得到解释：偏置的来源就是传递轴的天然引力）。</p><p><span class="marginnote">「胜率向量」翻译成大白话：别给我一个总分，给我分项成绩单——对激进型胜率多少、对稳健型多少、对诡辩型多少。平均分 70 可以是「全面 70」，也可以是「对某一类 0 分、被别处拉平」；后者才是上线后被用户一招打穿的隐患所在。</span></p><p>评测侧的机制结论同样直接：单一对手或单一基准给出的名次只约束传递轴上的一维投影。非传递审计至少要一个含已知环结构的对手组（哪怕就是几个刻意构造的「风格克制者」），报告模型对整组的胜率向量而不是标量均值——向量里方差最大的位置，就是最可能被真实对手利用的位置。</p><p>这张图回答的问题是：一个最小的环长什么样，凹陷审计顺着你最怕的对手怎么找补。</p>',7)),(B(),t(r,null,{default:a(()=>[n(e,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20LR%0A%20%20A%5B%22%E7%AD%96%E7%95%A5%20A%EF%BC%9A%E6%BF%80%E8%BF%9B%E6%B4%BE%22%5D%20--%3E%7C%22%E5%85%8B%E5%88%B6%22%7C%20B%5B%22%E7%AD%96%E7%95%A5%20B%EF%BC%9A%E7%A8%B3%E5%81%A5%E6%B4%BE%22%5D%0A%20%20B%20--%3E%7C%22%E5%85%8B%E5%88%B6%22%7C%20C%5B%22%E7%AD%96%E7%95%A5%20C%EF%BC%9A%E8%AF%A1%E8%BE%A9%E6%B4%BE%22%5D%0A%20%20C%20--%3E%7C%22%E5%85%8B%E5%88%B6%22%7C%20A%0A%20%20AUD%5B%22%E5%AE%A1%E8%AE%A1%EF%BC%9A%E5%AF%B9%E5%B7%B2%E7%9F%A5%E7%8E%AF%E5%AF%B9%E6%89%8B%E7%BB%84%E6%8A%A5%E8%83%9C%E7%8E%87%E5%90%91%E9%87%8F%22%5D%20--%3E%20V%7B%22%E5%90%91%E9%87%8F%E9%87%8C%E6%96%B9%E5%B7%AE%E6%9C%80%E5%A4%A7%E7%9A%84%E4%BD%8D%E7%BD%AE%22%7D%0A%20%20V%20--%3E%20PIT%5B%22%E6%9C%80%E5%8F%AF%E8%83%BD%E8%A2%AB%E7%9C%9F%E5%AE%9E%E5%AF%B9%E6%89%8B%E5%88%A9%E7%94%A8%E7%9A%84%E5%87%B9%E9%99%B7%22%5D%0A%20%20PIT%20--%3E%20POOL%5B%22%E5%85%8B%E5%88%B6%E5%9E%8B%E5%AF%B9%E6%89%8B%E4%BC%98%E5%85%88%E5%85%A5%E6%B1%A0%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[l(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>非传递性不是「无法评测」的借口，它只否定单标量；把胜负矩阵分解后，传递部分照常排序，循环维需要显式列出。本课也不宣称「环越多越好」：Czarnecki 等人 2020 的测量显示主轴仍是方差的大头，工程上先保传递轴的强度、再补循环维，顺序反了会把训练预算烧在打转上。</p><p><span class="marginnote">常见误区：听到非传递就以为「评测没意义了」。本课只否定单标量，不否定评测——分解之后强度轴照常排，循环维显式列成向量。另一头也别矫枉过正：一上来就猛挖环，预算烧在打转上，主轴强度反而没练起来。</span> 对语言模型还有一层未定：偏好对比里「非传递」既可能来自策略环，也可能来自标注噪声或偏好本身不可比（主干<a href="/llm/nash-learning-hf">Nash 学习</a>处理的是后者），两类非传递在同一名次表上混着，审计前要先归因。本课的环是对手空间的几何，下一课把它放到有成熟胜负判据的棋牌里，看那些环境教会自博弈什么。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>强弱关系天生非传递：胜负矩阵要分解成传递轴与循环维，单标量评测只能看见前者。</li><li>朴素自博弈沿传递轴推进有系统倾向，循环维表现为「噪声」，需要克制型对手显式覆盖。</li><li>对手课程在非传递空间里不能只按名次选对手，要按对当前模型胜率的凹陷选。</li><li>评测应报告对已知环结构对手组的胜率向量，而非标量均值；Elo 直接搬用隐含了「循环为零」的未论证假设。</li><li>偏好非传递要先归因：策略环、标注噪声、偏好不可比是三件事。</li><li>出处：Balduzzi 等 2019；Czarnecki 等 2020；Elo 1978；Chen 等 2024（SPIN）。</li></ul>',5))])}const u=i(p,[["render",d]]);export{D as __pageData,u as default};
